using sv_bf851dd1286c4b319734ebf02f480a17.Client.Services;

namespace sv_bf851dd1286c4b319734ebf02f480a17.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment(
            TrackingNumber: "PKG-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 2, 17, 0, 0, TimeSpan.FromHours(-5)),
            Updates:
            [
                new StatusUpdate("Package picked up", new DateTimeOffset(2026, 6, 25, 9, 0, 0, TimeSpan.FromHours(-5))),
                new StatusUpdate("Arrived at sorting facility", new DateTimeOffset(2026, 6, 25, 14, 30, 0, TimeSpan.FromHours(-5))),
                new StatusUpdate("Departed sorting facility", new DateTimeOffset(2026, 6, 26, 6, 0, 0, TimeSpan.FromHours(-5))),
                new StatusUpdate("In transit to destination", new DateTimeOffset(2026, 6, 26, 18, 45, 0, TimeSpan.FromHours(-5)))
            ]),

        ["PKG-002"] = new Shipment(
            TrackingNumber: "PKG-002",
            Status: "Delivered",
            Location: "Austin, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 26, 12, 0, 0, TimeSpan.FromHours(-5)),
            Updates:
            [
                new StatusUpdate("Package picked up", new DateTimeOffset(2026, 6, 22, 10, 0, 0, TimeSpan.FromHours(-5))),
                new StatusUpdate("In transit", new DateTimeOffset(2026, 6, 23, 8, 0, 0, TimeSpan.FromHours(-5))),
                new StatusUpdate("Out for delivery", new DateTimeOffset(2026, 6, 26, 7, 30, 0, TimeSpan.FromHours(-5))),
                new StatusUpdate("Delivered — signed by J. Smith", new DateTimeOffset(2026, 6, 26, 11, 15, 0, TimeSpan.FromHours(-5)))
            ]),

        ["PKG-003"] = new Shipment(
            TrackingNumber: "PKG-003",
            Status: "Processing",
            Location: "Seattle, WA",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 5, 17, 0, 0, TimeSpan.FromHours(-7)),
            Updates:
            [
                new StatusUpdate("Order placed", new DateTimeOffset(2026, 6, 27, 0, 30, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("Label created", new DateTimeOffset(2026, 6, 27, 1, 0, 0, TimeSpan.FromHours(-7)))
            ])
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

